import React, { useMemo, useState, useEffect } from 'react';
import { Link } from 'react-router-dom';

const categories = [
  { name: 'All', icon: '🎯' },
  { name: 'Books', icon: '📚' },
  { name: 'Notes', icon: '📝' },
  { name: 'Gadgets', icon: '⚙️' },
  { name: 'Electronics', icon: '🔌' },
  { name: 'Laptops', icon: '💻' },
  { name: 'Phones', icon: '📱' },
  { name: 'Accessories', icon: '🎧' },
  { name: 'Stationery', icon: '✏️' },
  { name: 'Bags', icon: '🎒' },
  { name: 'Calculators', icon: '🧮' },
  { name: 'Lab Equipment', icon: '🔬' },
  { name: 'Sports', icon: '⚽' },
  { name: 'Fashion', icon: '👕' },
  { name: 'Hostel Items', icon: '🛏️' },
  { name: 'Furniture', icon: '🪑' },
  { name: 'Cycles', icon: '🚴' },
  { name: 'Projects', icon: '🛠️' },
  { name: 'Coding Resources', icon: '💾' },
  { name: 'Tuition', icon: '👨‍🏫' },
  { name: 'Services', icon: '🤝' },
  { name: 'Others', icon: '🎁' }
];
const products = [
  {
    id: 1,
    title: 'Graph Theory Textbook Bundle',
    price: '24',
    category: 'Books',
    badge: 'Books',
    image:
      'https://images.unsplash.com/photo-1512820790803-83ca734da794?auto=format&fit=crop&w=800&q=80'
  },
  {
    id: 2,
    title: 'Noise Cancelling Headphones',
    price: '79',
    category: 'Gadgets',
    badge: 'Gadgets',
    image:
      'https://images.unsplash.com/photo-1512496015851-a90fb38ba796?auto=format&fit=crop&w=800&q=80'
  },
  {
    id: 3,
    title: 'Organic Chemistry Notes Pack',
    price: '15',
    category: 'Notes',
    badge: 'Notes',
    image:
      'https://images.unsplash.com/photo-1513258496099-48168024aec0?auto=format&fit=crop&w=800&q=80'
  },
  {
    id: 4,
    title: 'Gaming Laptop Charger',
    price: '39',
    category: 'Gadgets',
    badge: 'Gadgets',
    image:
      'https://images.unsplash.com/photo-1527430253228-e93688616381?auto=format&fit=crop&w=800&q=80'
  },
  {
    id: 5,
    title: 'Calculus Lecture Notes',
    price: '12',
    category: 'Notes',
    badge: 'Notes',
    image:
      'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=80'
  },
  {
    id: 6,
    title: 'Bluetooth Portable Speaker',
    price: '34',
    category: 'Gadgets',
    badge: 'Gadgets',
    image:
      'https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?auto=format&fit=crop&w=800&q=80'
  }
];

const Home = () => {
  const [activeCategory, setActiveCategory] = useState('All');
  const [search, setSearch] = useState('');
  const [sortBy, setSortBy] = useState('latest');
  const [favorites, setFavorites] = useState(new Set());
  const [loading, setLoading] = useState(false);

  const filteredProducts = useMemo(() => {
    let result = products.filter((product) => {
      const matchesCategory = activeCategory === 'All' || product.category === activeCategory;
      const matchesSearch = product.title.toLowerCase().includes(search.toLowerCase());
      return matchesCategory && matchesSearch;
    });

    // Sort products
    if (sortBy === 'price-low') {
      result.sort((a, b) => parseInt(a.price) - parseInt(b.price));
    } else if (sortBy === 'price-high') {
      result.sort((a, b) => parseInt(b.price) - parseInt(a.price));
    }

    return result;
  }, [activeCategory, search, sortBy]);

  const toggleFavorite = (productId) => {
    setFavorites((prev) => {
      const newFavorites = new Set(prev);
      if (newFavorites.has(productId)) {
        newFavorites.delete(productId);
      } else {
        newFavorites.add(productId);
      }
      return newFavorites;
    });
  };

  // Simulate loading
  useEffect(() => {
    setLoading(true);
    const timer = setTimeout(() => setLoading(false), 800);
    return () => clearTimeout(timer);
  }, [activeCategory, search]);

  return (
    <main className="page-shell home-page">
      <section className="hero-panel">
        <div className="hero-copy">
          <p className="eyebrow">Campus marketplace</p>
          <h1>Explore Marketplace</h1>
          <p className="hero-description">
            Discover student essentials, premium gadgets, curated notes, and exclusive campus deals in one premium marketplace.
          </p>
          <div className="hero-actions">
            <div className="search-card">
              <span className="search-icon">🔍</span>
              <input
                type="search"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Search books, gadgets, notes..."
                aria-label="Search marketplace"
              />
            </div>
            <Link to="/sell" className="gradient-btn">
              Post Item
            </Link>
          </div>
        </div>

        <div className="hero-panel-visual">
          <div className="hero-pill">✨ New listings every day</div>
          <div className="hero-highlight-card">
            <p>Top pick</p>
            <h2>Student-curated essentials with instant campus delivery.</h2>
          </div>
        </div>
      </section>

      <section className="filters-section">
        <div className="filters-row">
          {categories.map((category) => (
            <button
              key={category}
              className={`filter-pill ${activeCategory === category ? 'active' : ''}`}
              onClick={() => setActiveCategory(category)}
              type="button"
            >
              {category}
            </button>
          ))}
        </div>
      </section>

      {/* Marketplace Toolbar */}
      <section className="marketplace-toolbar">
        <div className="toolbar-left">
          <select
            value={sortBy}
            onChange={(e) => setSortBy(e.target.value)}
            className="sort-dropdown"
            aria-label="Sort products"
          >
            <option value="latest">Latest</option>
            <option value="price-low">Price: Low to High</option>
            <option value="price-high">Price: High to Low</option>
          </select>

          <button
            type="button"
            className={`favorites-toggle ${favorites.size > 0 ? 'active' : ''}`}
            title={`${favorites.size} favorite${favorites.size !== 1 ? 's' : ''}`}
          >
            <span className="heart-icon">❤️</span>
            <span>{favorites.size > 0 ? favorites.size : 'Favorites'}</span>
          </button>
        </div>

        <div className="results-count">
          <span style={{ color: '#cbd5f5', fontWeight: '600' }}>
            {filteredProducts.length} result{filteredProducts.length !== 1 ? 's' : ''}
          </span>
        </div>
      </section>

      {/* Loading Skeleton */}
      {loading && (
        <section className="products-grid">
          {[1, 2, 3, 4, 5, 6].map((i) => (
            <div key={i} className="skeleton-card">
              <div className="skeleton-image skeleton"></div>
              <div className="skeleton-body">
                <div className="skeleton-title skeleton"></div>
                <div className="skeleton-price skeleton"></div>
                <div className="skeleton-category skeleton"></div>
              </div>
            </div>
          ))}
        </section>
      )}

      {/* Products Grid or Empty State */}
      {!loading && filteredProducts.length > 0 ? (
        <section className="products-grid">
          {filteredProducts.map((product) => (
            <article key={product.id} className="product-card">
              <div className="card-image" style={{ backgroundImage: `url(${product.image})` }}>
                <span className="badge">{product.badge}</span>
                <button
                  className="bookmark-icon"
                  type="button"
                  onClick={() => toggleFavorite(product.id)}
                  style={{
                    background: favorites.has(product.id)
                      ? 'linear-gradient(135deg, #ec4899, #f43f5e)'
                      : 'rgba(15, 23, 42, 0.85)',
                    transform: favorites.has(product.id) ? 'scale(1.1)' : 'scale(1)',
                    transition: 'all 0.2s ease'
                  }}
                  title={favorites.has(product.id) ? 'Remove from favorites' : 'Add to favorites'}
                >
                  {favorites.has(product.id) ? '❤️' : '🤍'}
                </button>
              </div>
              <div className="card-body">
                <h3>{product.title}</h3>
                <p className="card-price">${product.price}</p>
                <div className="card-meta">
                  <span className="card-category">{product.category}</span>
                  <Link to="/add-product" className="card-link">
                    View
                  </Link>
                </div>
              </div>
            </article>
          ))}
        </section>
      ) : !loading ? (
        <section className="empty-state">
          <div className="empty-state-icon">📦</div>
          <h2 className="empty-state-title">No products found</h2>
          <p className="empty-state-description">
            {search
              ? `No results for "${search}". Try adjusting your search or browse all products.`
              : activeCategory !== 'All'
              ? `No products in the ${activeCategory} category. Try another category or post a new item!`
              : 'No products available right now. Be the first to post one!'}
          </p>
          {search || activeCategory !== 'All' ? (
            <>
              <button
                type="button"
                className="empty-state-action"
                onClick={() => {
                  setSearch('');
                  setActiveCategory('All');
                }}
              >
                ← Clear filters
              </button>
            </>
          ) : (
            <Link to="/sell" className="empty-state-action">
              ➕ Post first item
            </Link>
          )}
        </section>
      ) : null}
    </main>
  );
};

export default Home;
